SELECT COUNT(*), COUNT(*) FILTER (WHERE s.days_past_due>=30), ROUND(100.0*COUNT(*) FILTER (WHERE s.days_past_due>=30)/COUNT(*),2), ROUND(SUM(s.arrears_amount),0) FROM loan_monthly_snapshot s JOIN loan l USING (loan_id) JOIN property pr ON pr.property_id=l.property_id JOIN dim_postcode d ON d.postcode=pr.postcode WHERE s.snapshot_date = DATE '2025-12-31' AND s.loan_status <> 'Closed' AND d.state='NT'
